-- Tab Gaji & Premi (v88): per akun (COA) kelompok BIAYA PANEN dan TRANSPORT PANEN per bulan; ribu Rp. PMY = 2131+2122, afd B dikeluarkan.
-- Hasil: satu baris per BA x COA: [array aktual 12 bulan, array budget 12 bulan] (bulan di luar periode = 0). Ganti batas BULAN< sesuai periode.
WITH s AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, COA, ANY_VALUE(LEVEL_3) nm, MONTH(BULAN) m, SUM(RP_ACTUAL) a, SUM(RP_BUDGET) b
 FROM PRD_DB_PRESENTATION.PRS_COST.ESTATE_COST
 WHERE GROUP_LEVEL IN ('BIAYA PANEN','TRANSPORT PANEN') AND KODE_BA IN ('2121','2124','2131','2122')
  AND NOT (DECODE(KODE_BA,'2122','2131',KODE_BA)='2131' AND KODE_AFD='B') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01'
 GROUP BY 1,2,4)
SELECT ba, COA,
 ARRAY_TO_STRING(ARRAY_CONSTRUCT(ROUND(SUM(IFF(m=1,a,0))/1000),ROUND(SUM(IFF(m=2,a,0))/1000),ROUND(SUM(IFF(m=3,a,0))/1000),ROUND(SUM(IFF(m=4,a,0))/1000),ROUND(SUM(IFF(m=5,a,0))/1000),ROUND(SUM(IFF(m=6,a,0))/1000),ROUND(SUM(IFF(m=7,a,0))/1000),ROUND(SUM(IFF(m=8,a,0))/1000),ROUND(SUM(IFF(m=9,a,0))/1000)),',') act,
 ARRAY_TO_STRING(ARRAY_CONSTRUCT(ROUND(SUM(IFF(m=1,b,0))/1000),ROUND(SUM(IFF(m=2,b,0))/1000),ROUND(SUM(IFF(m=3,b,0))/1000),ROUND(SUM(IFF(m=4,b,0))/1000),ROUND(SUM(IFF(m=5,b,0))/1000),ROUND(SUM(IFF(m=6,b,0))/1000),ROUND(SUM(IFF(m=7,b,0))/1000),ROUND(SUM(IFF(m=8,b,0))/1000),ROUND(SUM(IFF(m=9,b,0))/1000)),',') bud
FROM s GROUP BY 1,2 HAVING SUM(ABS(a))+SUM(ABS(b))>0 ORDER BY 1,2;
